package main

import (
	"bufio"
	"fmt"
	"os"
)

func findGreeting(str string) string {
	word := "hello"
	i := 0
	for _, l := range str {
		if i < len(word) && l == rune(word[i]) {
			i++
		}
	}
	if i == len(word) {
		return "YES"
	}
	return "NO"
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var data string
	if scanner.Scan() {
		data = scanner.Text()
	}
	res := findGreeting(data)
	fmt.Println(res)
}

